static inline u16 get_unaligned_le16(const void *p) /* <=== get_unaligned_le16 */ 
{
	return __get_unaligned_cpu16((const u8 *)p);
}

static inline u16 get_unaligned_le16(const void *p) /* <=== get_unaligned_le16 */ 
{
	return le16_to_cpup((__le16 *)p);
}

static inline u16 __get_unaligned_le16(const u8 *p) /* <=== __get_unaligned_le16 */ 
{
	return p[0] | p[1] << 8;
}

static inline u16 get_unaligned_le16(const void *p) /* <=== get_unaligned_le16 */ 
{
	const u8 *_p = p;
	return _p[0] | _p[1] << 8;
}

static inline u16 get_unaligned_le16(const void *p) /* <=== get_unaligned_le16 */ 
{
	return __get_unaligned_le16((const u8 *)p);
}

static inline u16 get_unaligned_le16(const void *p) /* <=== get_unaligned_le16 */ 
{
	return le16_to_cpu(sh4a_get_unaligned_cpu16(p));
}

static inline u16 sh4a_get_unaligned_cpu16(const u8 *p) /* <=== sh4a_get_unaligned_cpu16 */ 
{
#ifdef __LITTLE_ENDIAN
	return p[0] | p[1] << 8;
#else
	return p[0] << 8 | p[1];
#endif
}

